function request(type,extra={},onProgress){return new Promise((resolve,reject)=>{const channel=new MessageChannel();let timer;const stop=()=>{clearTimeout(timer);channel.port1.close();},reset=()=>{clearTimeout(timer);timer=setTimeout(()=>{stop();reject(Error('下载长时间无进展，已校验资源保留；联网后可重试'));},65000);};reset();channel.port1.onmessage=e=>{reset();if(e.data.progress){onProgress?.(e.data);return;}stop();e.data.ok?resolve(e.data.state):reject(Error(e.data.error));};controller.postMessage({type,...extra},[channel.port2]);});}
window.SS2_CACHE_REQUEST=request;
const SAVE_KEY='ss2.v6-web:'+new URL('./',location.href).pathname+'save';
function saved(){try{const e=JSON.parse(localStorage.getItem(SAVE_KEY));return e?JSON.parse(e.payload):null;}catch{return null;}}
function safe(){const s=saved();return !s||s.phase==='over'||(s.phase==='shop'&&s.turn===1&&!s.team.length&&!s.history.length);}
function showReady(s){cacheState=s;if(!selectedManifest){status.textContent="正在准备游戏…";return;}const m=selectedManifest;update.hidden=!(s.pending||(m&&m.id!==s.active));rollback.hidden=!s.previous;const complete=m&&(!m.mode||s.complete?.[m.id]||s.protocol!==2);status.textContent=(m?.title||'V6')+' · '+(m?.id||s.active)+' · '+(complete?'完整离线包已就绪':'按场景加载 · 尚未下载完整离线包')+(s.pending?' · 有新版可切换':'');offline.hidden=!!complete;offline.disabled=!m||fullBusy;if(m)offline.textContent='下载完整离线包（约'+Math.ceil(m.files.reduce((n,f)=>n+f.size,0)/1000000)+' MB）';pause.hidden=!fullBusy;}
function progress(prefix,p){status.textContent=prefix+' '+(p.done/1000000).toFixed(1)+' / '+(p.total/1000000).toFixed(1)+' MB';}
async function switchVersion(type){if(!safe()){status.textContent='请结束当前整局后再切换，当前局继续使用原版本。';return;}try{if(!(type==='ACTIVATE'&&!cacheState.pending&&selectedManifest.id!==cacheState.active)){const next=await request(type);if(type==='ROLLBACK')localStorage.setItem(SAVE_KEY+'.ui-rollback',next.active);else localStorage.removeItem(SAVE_KEY+'.ui-rollback');}const s=saved();if(s&&window.SS2Storage){delete s.webRelease;delete s.webRules;localStorage.setItem(SS2Storage.KEY,SS2Storage.exportSave(s));}location.reload();}catch(e){status.textContent=e.message;}}
update.onclick=()=>switchVersion('ACTIVATE');rollback.onclick=()=>switchVersion('ROLLBACK');
offline.onclick=async()=>{if(fullBusy)return;fullBusy=true;offline.disabled=true;pause.hidden=false;try{showReady(await request(cacheState.protocol===2?'FULL':'PREPARE',{release:selectedManifest.id},p=>progress('下载完整离线包',p)));}catch(e){status.textContent=e.message+'；已下载部分保留。';}finally{fullBusy=false;offline.disabled=false;pause.hidden=true;}};
pause.onclick=()=>request('CANCEL').catch(e=>status.textContent=e.message);
const loaderButton=document.getElementById('web-loader-update');
if(loaderButton)loaderButton.onclick=()=>{if(!registration?.waiting)return;navigator.serviceWorker.addEventListener('controllerchange',()=>location.reload(),{once:true});registration.waiting.postMessage({type:'ACTIVATE_LOADER'});};
function offerLoader(){if(loaderButton)loaderButton.hidden=!(registration?.waiting&&cacheState?.protocol!==2);}
function saveEnvelope(s){const payload=JSON.stringify(s);let h=2166136261;for(let i=0;i<payload.length;i++)h=Math.imul(h^payload.charCodeAt(i),16777619);return JSON.stringify({format:'SS2-LOCAL-SAVE',version:1,checksum:(h>>>0).toString(16).padStart(8,'0'),payload});}
async function importChoice(){const d=document.createElement('dialog'),p=document.createElement('p');p.textContent='这份历史格式存档没有网页版规则标记，请选择用哪套规则恢复。V6历史规则会加载原发行包；当前版本规则会明确迁入本版。';d.append(p);document.body.append(d);return new Promise(ok=>{for(const[label,value]of [['按V6历史规则恢复','legacy'],['按当前版本规则导入','current'],['取消导入','cancel']]){const b=document.createElement('button');b.textContent=label;b.onclick=()=>{d.close();d.remove();ok(value);};d.append(b);}d.addEventListener('cancel',e=>{e.preventDefault();d.close();d.remove();ok('cancel');});d.showModal();});}
window.SS2_RESUME_SAVE=async text=>{if(typeof text!=='string'||text.length>12000000)throw Error('存档大小不合法');const e=JSON.parse(text),s=JSON.parse(e.payload),rebuilt=JSON.parse(saveEnvelope(s));if(e.format!=='SS2-LOCAL-SAVE'||e.version!==1||e.checksum!==rebuilt.checksum||e.payload!==rebuilt.payload)throw Error('存档格式或校验不一致');if(s.webRules===selectedManifest.rules)return false;let target=s.webRelease;if(selectedManifest.rules.startsWith('v8-')&&!target&&!s.webRules&&s.version==='local-base-18-v1'&&['cangjin-30','local-base-18'].includes(s.packId||'local-base-18')){const choice=await importChoice();if(choice==='cancel')return true;if(choice==='legacy')target='v6-web-r2';}if(target&&target!==selectedManifest.id){if(!cacheState.releases[target]){try{cacheState=await request('CHECK');}catch{}if(!cacheState.releases[target])cacheState=await request('RESTORE',{release:target},p=>progress('恢复历史规则资源',p));}const old=cacheState.releases[target];if(!old)throw Error('历史发行包不在本机');if(old.rules!==selectedManifest.rules){const previous=localStorage.getItem(SAVE_KEY),current=window.SS2Storage?.load().state;if(current&&(current.team.length||current.history.length)&&window.SS2Storage?.retainRun){const retained=SS2Storage.retainRun(current);if(!retained.ok)throw Error(retained.warning);}s.webRelease=target;s.webRules=old.rules;if(previous)localStorage.setItem(SAVE_KEY+'.backup',previous);localStorage.setItem(SAVE_KEY,saveEnvelope(s));location.reload();return true;}}if(s.webRules&&s.webRules!==selectedManifest.rules)throw Error('该存档的规则无法与当前发行版绑定，请保留原文件');return false;};
document.getElementById('import-file')?.addEventListener('change',async e=>{if(selectedManifest?.rules.startsWith('v8-')||!e.target.files[0])return;e.stopImmediatePropagation();try{if(!await window.SS2_RESUME_SAVE(await e.target.files[0].text()))await e.target.onchange?.call(e.target,{target:e.target});}catch(error){status.textContent='存档未替换：'+error.message;}},true);
function presentationFor(m){const p=SS2_UI_PATCH,pin=p.pins[m.id],ready=cacheState.releases[p.id];return localStorage.getItem(SAVE_KEY+'.ui-rollback')!==m.id&&pin&&ready&&ready.rules===m.rules&&m.rules===p.rules&&m.css===pin.css&&JSON.stringify(m.scripts)===JSON.stringify(pin.scripts)?p:null;}
async function load(m){const ui=presentationFor(m);window.SS2_WEB_UI_RELEASE=ui?.id||m.id;window.SS2_WEB_UI_SCRIPTS=m.scripts.map(p=>ui&&m.files.find(f=>f.path===p)?.label==='src/app.js'?ui.app:p);const html=SS2_RELEASE_SHELLS[ui?.id||m.id];if(!html)throw Error('未找到此版本的界面，请保留存档');const toolbar=document.querySelector('.web-toolbar');const parsed=new DOMParser().parseFromString(html,'text/html');for(const e of parsed.querySelectorAll('script,.web-toolbar'))e.remove();for(const e of [...document.body.children])if(e!==toolbar)e.remove();for(const e of [...parsed.body.childNodes])document.body.append(document.importNode(e,true));const firstLoad=document.createElement('p');firstLoad.id='web-first-load';firstLoad.className='web-first-load';firstLoad.setAttribute('role','status');firstLoad.textContent='正在准备游戏，请稍候…';document.body.prepend(firstLoad);window.SS2_WEB_UI_READY=()=>{delete document.body.dataset.webBoot;firstLoad.remove();};if(!ui&&m.id!=="v6-web-rules-uiux-r1")window.SS2_WEB_UI_READY();const slot=document.getElementById('web-settings-slot');if(slot){const h=document.createElement('h3');h.textContent='版本与离线';slot.append(h,toolbar);const b=document.createElement('button');b.textContent='本机出战记录';b.onclick=()=>{document.getElementById('game-settings').close();window.SS2Lineups.show();};slot.append(b);}else document.body.prepend(toolbar);selectedManifest=m;window.SS2_WEB_RELEASE=m.id;window.SS2_WEB_RULES=m.rules;window.SS2_WEB_MANIFEST=m;window.SS2_ASSET_URL=m.assetUrls||{};window.SS2_ACTORS={};window.SS2_WEB_READY=()=>showReady(cacheState);const historical=!m.rules.startsWith('v8-');const retained=document.getElementById('saved-runs');if(retained)retained.hidden=historical;const footer=document.querySelector('footer span:last-child');if(footer)footer.textContent=historical?'历史V6 · 本机存档 · 上传需主动同意':'进度仅保存在当前设备';const css=document.createElement('link');css.rel='stylesheet';css.href=ui?.css||m.css;document.head.append(css);for(const src of SS2_WEB_UI_SCRIPTS)await new Promise((ok,no)=>{const script=document.createElement('script');script.src=src;script.onload=ok;script.onerror=()=>no(Error('载入失败：'+src));document.body.append(script);});if(SS2_LEGACY_GROUP_SPEC.pins[m.id]&&cacheState.releases[SS2_UI_PATCH.id]&&localStorage.getItem(SAVE_KEY+'.ui-rollback')!==m.id)await new Promise((ok,no)=>{const el=document.createElement('script');el.src="objects/c4b2190aee7ec5b5a2b9bcae053549adca077969eedd4c86e4577dcce8267c88.js";el.onload=ok;el.onerror=()=>no(Error('历史升级组显示未准备好'));document.body.append(el);});document.body.dataset.webRelease=m.id;}
// Presentation only for immutable historical web shells. No state/RNG writes.
function installPCHeadOverlay(){
 if(selectedManifest.id===SS2_PC_HEAD_RELEASE||window.SS2_PC_HEAD_OVERLAY)return;
 const team=document.getElementById('team');if(!team)return;
 const media=matchMedia('(min-width:901px)'),attempted=new WeakMap();let queued=false,busy=false,again=false;
 const style=document.createElement('style');style.textContent='@media(min-width:901px){#team .pc-team-portrait{display:inline-grid;place-items:center;flex:0 0 80px;width:80px;height:80px;margin-right:8px;pointer-events:none}#team .pc-team-portrait>img{width:80px;height:80px;max-width:100%;object-fit:contain}}@media(min-width:901px) and (max-width:1000px){#team .pc-team-portrait{margin:0 auto 5px}}';document.head.append(style);
 const retry=document.createElement('button');retry.id='web-heads-retry';retry.textContent='重试队伍头像';retry.hidden=true;document.querySelector('.web-toolbar').append(retry);
 function schedule(){if(queued)return;queued=true;queueMicrotask(()=>{queued=false;refresh();});}
 async function refresh(){
  if(!media.matches||!cacheState.releases[SS2_PC_HEAD_RELEASE])return;
  if(busy){again=true;return;}busy=true;
  try{
   const nodes=[...team.querySelectorAll('.team-slot canvas[data-portrait]')].slice(0,5),todo=nodes.filter(c=>attempted.get(c)!=='done'&&attempted.get(c)!=='failed');
   for(const h of team.querySelectorAll('.team-slot>.mobile-head-holder'))h.classList.add('pc-team-portrait');
   const rows=todo.map(c=>({c,path:SS2_PC_HEADS[c.dataset.portrait]})).filter(x=>x.path);
   if(!rows.length)return;
   rows.forEach(({c})=>attempted.set(c,'done'));
   try{
    await request('ENSURE',{release:SS2_PC_HEAD_RELEASE,paths:[...new Set(rows.map(x=>x.path))]});
    await Promise.all(rows.map(async({c,path})=>{const image=new Image();image.alt=c.getAttribute('aria-label')||'武将头像';image.decoding='async';image.src=path;await image.decode();if(!c.isConnected||!media.matches)return;const holder=document.createElement('span');holder.className='pc-team-portrait';holder.append(image);c.replaceWith(holder);}));
    retry.hidden=true;team.dataset.headsState='ready';
   }catch{rows.forEach(({c})=>attempted.set(c,'failed'));retry.hidden=false;team.dataset.headsState='retry';retry.title='头像未准备好，原角色图仍可使用。联网后重试。';}
  }finally{busy=false;if(again){again=false;schedule();}}
 }
 function retryHeads(){for(const c of team.querySelectorAll('canvas[data-portrait]'))attempted.delete(c);schedule();}
 retry.onclick=retryHeads;media.addEventListener('change',retryHeads);window.addEventListener('online',retryHeads);
 new MutationObserver(schedule).observe(team,{childList:true,subtree:true});
 window.SS2_PC_HEAD_OVERLAY={refresh:retryHeads,release:SS2_PC_HEAD_RELEASE};schedule();
}

(async()=>{try{if(!('serviceWorker'in navigator)||!window.isSecureContext)throw Error('请通过 HTTPS 打开');registration=await navigator.serviceWorker.register('./sw.js',{scope:'./',updateViaCache:'none'});registration.addEventListener('updatefound',()=>registration.installing?.addEventListener('statechange',offerLoader));await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(ok=>navigator.serviceWorker.addEventListener('controllerchange',ok,{once:true}));controller=navigator.serviceWorker.controller;cacheState=await request('STATUS');offerLoader();if(!cacheState.active)cacheState=await request(cacheState.protocol===2?'ENTRY':'PREPARE',{},p=>progress('准备开始游戏',p));
 const s=saved(),pinned=s?.webRelease,m=cacheState.releases[pinned||cacheState.active];if(!m)throw Error('本局对应版本不在本机，请保留存档并回退原发行版');if((SS2_UI_PATCH.pins[m.id]||SS2_LEGACY_GROUP_SPEC.pins[m.id])&&!cacheState.releases[SS2_UI_PATCH.id]){try{cacheState=await request('CHECK');}catch{}}showReady(cacheState);await load(m);showReady(cacheState);installPCHeadOverlay();
 if(navigator.storage?.persist)navigator.storage.persist().then(persistent=>{status.title=persistent?'浏览器已允许持久存储':'浏览器可能回收缓存，请导出保留存档。';}).catch(()=>{});
 try{showReady(await request(cacheState.protocol===2?'CHECK':'PREPARE'));window.SS2_PC_HEAD_OVERLAY?.refresh();}catch(e){status.textContent='继续使用本机版本；版本检查未完成：'+e.message;}
 }catch(e){delete document.body.dataset.webBoot;document.getElementById('web-first-load')?.remove();status.textContent='载入未完成：'+e.message;const warning=document.getElementById('warning');warning.hidden=false;warning.textContent=status.textContent;console.error(e.message);}})();
